/bin/bash -lc "python - <<'PY'
import urllib.request, json
for repo in ['bioconductor-deseq2','gseapy','bioconductor-org.mm.eg.db','bioconductor-apeglm','bioconductor-ashr']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20'
    try:
        data=json.load(urllib.request.urlopen(url, timeout=20))
        print('\\n', repo)
        for t in data.get('tags', [])[:10]:
            print(t.get('name'))
    except Exception as e:
        print(repo, 'ERR', e)
PY"
